PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

# La cuota de cada uno es sobre la suma de los pares mayores de la institución
# en el grafo, no sobre su total: es un techo de la cuota real.
SELECT ?proveedor ?nombre ?contratado ?cuota
WHERE {
  { SELECT ?institucion (SUM(?monto) AS ?total)
    WHERE { VALUES ?institucion { {{institucion}} }
            ?c a soc:Contratacion ; soc:contratante ?institucion ; soc:montoContratado ?monto }
    GROUP BY ?institucion }
  { SELECT ?institucion ?proveedor (SUM(?monto) AS ?contratado)
    WHERE { VALUES ?institucion { {{institucion}} }
            ?c a soc:Contratacion ; soc:contratante ?institucion ;
               soc:contratista ?proveedor ; soc:montoContratado ?monto }
    GROUP BY ?institucion ?proveedor
    ORDER BY DESC(?contratado) ?proveedor
    LIMIT 5 }
  OPTIONAL { ?proveedor rdfs:label ?nombre }
  BIND(ROUND(1000 * ?contratado / ?total) / 10 AS ?cuota)
}
ORDER BY DESC(?contratado) ?proveedor

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>

SELECT ?institucion ?nombre ?contratos ?contratado
WHERE {
  ?c a soc:Contratacion ;
     soc:contratista {{proveedor}} ;
     soc:contratante ?institucion ;
     soc:numeroDeContratos ?contratos ;
     soc:montoContratado ?contratado .
  ?institucion schema:name ?nombre .
}
ORDER BY DESC(?contratado) ?institucion

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?obra ?nombre ?estado ?costo ?ejecutora
WHERE {
  ?obra a soc:ProyectoDeInversion ;
        soc:enProvincia {{provincia}} ;
        rdfs:label ?nombre ;
        soc:estado ?estado ;
        soc:valorEstimado ?costo .
  OPTIONAL { ?obra soc:ejecutadoPor ?i . ?i schema:name ?ejecutora }
  FILTER NOT EXISTS { ?contrato a soc:Contrato ; soc:paraProyecto ?obra }
}
ORDER BY DESC(?costo) ?obra

PREFIX soc: <https://w3id.org/socratico/def/core#>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT ?conjunto ?titulo (GROUP_CONCAT(DISTINCT ?formato; separator=", ") AS ?formatos)
WHERE {
  ?conjunto a soc:ConjuntoDeDatos ;
            soc:publicadaPor {{institucion}} ;
            dct:title ?titulo .
  OPTIONAL { ?conjunto soc:formato ?formato }
}
GROUP BY ?conjunto ?titulo
ORDER BY ?titulo ?conjunto
